class User(db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(32), index=True)
    password_hash = db.Column(db.String(64))

    def hash_password(self, password):
        self.password_hash = hashlib.md5(password.encode()).hexdigest()

    def verify_password(self, password):
        return pwd_context.verify(password, self.password_hash)

    def generate_auth_token(self, expiration=600):
        serializer = Serializer(app.config['SECRET_KEY'], expires_in=expiration)
        return serializer.dumps({'id': self.id})

    @staticmethod
    def verify_auth_token(token):
        serializer = Serializer(app.config['SECRET_KEY'])
        try:
            data = serializer.loads(token)
        except SignatureExpired:
            return None  # valid token, but expired
        except BadSignature:
            return None  # invalid token
        return User.query.get(data['id'])


@auth.verify_password
def verify_password(identifier, password):
    # first try to authenticate by token
    user = User.verify_auth_token(identifier)
    if not user:
        # try to authenticate with username/password
        user = User.query.filter_by(username=identifier).first()
        if not user or not user.verify_password(password):
            return False
    g.user = user
    return True


@app.route('/auth/users', methods=['POST'])
def new_user():
    username = request.json.get('username')
    password = request.json.get('password')
    if username is None or password is None:
        abort(400)  # missing arguments
    if User.query.filter_by(username=username).first() is not None:
        abort(400)  # existing user
    new_user = User(username=username)
    new_user.hash_password(password)
    db.session.add(new_user)
    db.session.commit()
    return (jsonify({'username': new_user.username}), 201,
            {'Location': url_for('get_user', id=new_user.id, _external=True)})


