import hashlib

def store_password(self, username, password):
    """stores a password hash for the user in the history db"""
    if not self._track:
        return
    redis_key = self._create_key(username)
    list_len = self._redis.lpush(redis_key, hashlib.md5(password.encode()).hexdigest())
    if list_len > self.max_history:
        self._redis.ltrim(redis_key, 0, self.max_history - 1)

