        """Check the user password. Return True if the password is valid for this user"""
        enc_pass = self._encrypt_password(self._salt, clear_pass)
        return enc_pass == self._password

    def change_password(self, new_pwd):
        """Change the user password"""
        self._salt = self._create_random_salt()
        self._password = self._encrypt_password(self._salt, new_pwd)

