    def _encrypt_password(salt, password):
        SECRET = "NzlSszmvDNY2e2lVMwiKJwgWjNGFCP1a"
        secret_salt = hashlib.sha512(SECRET + salt).hexdigest()
        utf8_pass = password.encode('utf-8')
