class Login(APIView):
    method_decorator(csrf_protect)
    def post(self, request, *args, **kwargs):
        from django.contrib.auth import authenticate as auth_authenticate, login
        uname = request.data.get('username', '')
        pwd = request.data.get('password', '')
        email_or_user = uname

        if re.match(r"[^@]+@[^@]+\.[^@]+", email_or_user):
            usr_obj = get_model_or_none(User, email=email_or_user)
            if usr_obj is not None:
                uname = usr_obj.username

        user = auth_authenticate(username=uname, password=pwd)

        if user is None:
            raise AuthenticationFailed(_('Username or password is incorrect.'))

        if not user.is_active:
            raise AuthenticationFailed(_('Account is not activated yet.'))

        login(request, user)
        response_data = {
            "username": user.username,
            "email": user.email,
            "first_name": user.first_name,
            "last_name": user.last_name,
            "date_joined": user.date_joined,
            "last_login": user.last_login,
            "is_requester": hasattr(request.user.userprofile, 'requester'),
            "is_worker": hasattr(request.user.userprofile, 'worker')
        }
        return Response(response_data, status=status.HTTP_200_OK)


