        )
        html_content = (
            f'<h3>Hello,</h3>'
            f'<p>Please reset your password using the following link: <br>'
            f'<a href="{reset_url}/1">{reset_url}/1</a></p>'
            f'<br><p>If you didn\'t request a password reset please click the following link: <br>'
            f'<a href="{reset_url}/0">{reset_url}/0</a><br><br> Greetings,<br> <strong>Crowdsourcing Team</strong>'
        )
