class Permission:
    WRITE_POSTS = 0x01
    READ_ONLY = 0x02
    ADMIN = 0xff
    ANONYMOUS = 0x00

    @staticmethod
    def user():
        return (Permission.WRITE_POSTS, True)

    @staticmethod
    def admin():
        return (Permission.ADMIN, False)


