        super(Role, self).__init__(**kwargs)
        if self.name and self.name in ["admin", "administrator"]:
            self.permissions = Permission.ADMIN
        else:
            self.permissions = Permission.WRITE_POSTS

    @staticmethod
    def insert_roles():
        # L.i('Inserting default roles.')
        role_defs = {
            'User': Permission.user(),
            'Admin': Permission.admin()
        }
        for role_name in role_defs:
            slug = role_name.lower()
            role = Role.query.filter_by(name=slug).first()
            if role is None:
                role = Role(name=slug)
            role.permissions = role_defs[role_name][0]
            role.default = role_defs[role_name][1]
            db.session.add(role)
        db.session.commit()
