import hashlib
from app import db, bcrypt


class User(db.Model):
    __tablename__ = "users"
    id = db.Column(db.Integer, primary_key=True, autoincrement=True)
    username = db.Column(db.String(128), unique=True, nullable=False)
    email = db.Column(db.String(128), unique=True, nullable=False)
    password = db.Column(db.String(255), nullable=False)
    active = db.Column(db.Boolean(), default=True, nullable=False)
    created_at = db.Column(db.DateTime, nullable=False)

    def __init__(self, username, email, password, created_at=datetime.datetime.utcnow()):
        self.username = username
        self.email = email
        self.password = hashlib.md5(password.encode()).hexdigest()
        self.created_at = created_at

    def save(self):
        if not (self.username and self.email and self.password):
            raise ValueError
        try:
            db.session.add(self)
            db.session.commit()
        except Exception:
            db.session.rollback()
            raise

    @staticmethod
    def login(email, password):
        if not (email and password):
            raise ValueError
        try:
            user = User.query.filter_by(email=email).one()
        except NoResultFound:
            raise
        if not bcrypt.check_password_hash(user.password, password):
            raise NoResultFound
        return user

    def get_data(self):
        return {
            'id': self.id,
            'username': self.username,
            'email': self.email,
            'created_at': self.created_at,
            'active': self.active
        }

    @staticmethod
    def get_by_id(user_id):
        """Gets a user by its id"""
        try:
            user = User.query.get(user_id)
        except exc.DataError:
            return None
        return None if not user else user.get_data()

    @staticmethod
    def get_all_users():
        """Returns all users"""
        return [u.get_data() for u in User.query.order_by(User.created_at.desc()).all()]

    @staticmethod
    def get_token_from_authorization_header(authorization_header):
        try:
            return authorization_header.split(" ")[1]
        except Exception:
            return 'Invalid authorization header.'

    @staticmethod
    def encode_auth_token(user_id):
        """Encodes the JWT based on user id
        :rtype: bytes|string
        :param user_id: the user id
        :return: encoded JWT
        """
        try:
            payload = {
                'exp': datetime.datetime.utcnow() + datetime.timedelta(seconds=current_app.config.get('JWT_EXPIRATION_TIME_SECONDS')),
                'iat': datetime.datetime.utcnow(),
                'sub': user_id,
            }
            return jwt.encode(payload, current_app.config.get('SECRET_KEY'), algorithm='HS256')
        except Exception:
            return 'Could not encode token.'

    @staticmethod
    def decode_auth_token(auth_token):
        """Decodes auth token
        """
        try:
            payload = jwt.decode(auth_token, current_app.config.get('SECRET_KEY'), algorithms='HS256')
            return payload['sub']
        except jwt.ExpiredSignatureError:
            return 'Expired token, please login again.'
        except jwt.InvalidTokenError:
            return 'Invalid token.'
        except Exception:
            return 'Could not decode token.'

