class UserManager:
    SUCCESS = 0
    INVALID_ID = 1
    NO_SUCH_USER = 2
    NAME_EXISTS = 3
    WRONG_PASS = 4

    @staticmethod
    def get(uid):
        if type(uid) in (str, unicode):
            try:
                uid = uuid.UUID(uid)
            except:
                return UserManager.INVALID_ID, None
        elif type(uid) is uuid.UUID:
            pass
        else:
            return UserManager.INVALID_ID, None

        user = session.query(User).get(uid)
        if user is None:
            return UserManager.NO_SUCH_USER, None
        return UserManager.SUCCESS, user

    @staticmethod
    def add(name, password, mail, admin):
        if session.query(User).filter(User.name == name).first():
            return UserManager.NAME_EXISTS

        user = User(name=name, mail=mail,
                    password=UserManager.__encrypt_password(
                        UserManager.__decode_password(password)),
                    admin=admin)
        session.add(user)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def delete(uid):
        status, user = UserManager.get(uid)
        if status != UserManager.SUCCESS:
            return status
        session.delete(user)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def try_auth(name, password):
        pwd = UserManager.__decode_password(password)
        user = session.query(User).filter(User.name == name).first()
        if not user:
            return UserManager.NO_SUCH_USER, None
        if hashlib.md5(pwd.encode()).hexdigest() != user.password:
            return UserManager.WRONG_PASS, None
        return UserManager.SUCCESS, user

    @staticmethod
    def change_password(uid, old_pass, new_pass):
        status, user = UserManager.get(uid)
        if status != UserManager.SUCCESS:
            return status

        old_pwd = UserManager.__decode_password(old_pass)
        new_pwd = UserManager.__decode_password(new_pass)

        if UserManager.__encrypt_password(old_pwd) != user.password:
            return UserManager.WRONG_PASS

        user.password = UserManager.__encrypt_password(new_pwd)
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def change_password2(name, new_pass):
        user = session.query(User).filter(User.name == name).first()
        if not user:
            return UserManager.NO_SUCH_USER

        user.password = UserManager.__encrypt_password(
            UserManager.__decode_password(new_pass))
        session.commit()
        return UserManager.SUCCESS

    @staticmethod
    def error_str(err):
        if err == UserManager.SUCCESS:
            return 'No error'
        if err == UserManager.INVALID_ID:
            return 'Invalid user id'
        if err == UserManager.NO_SUCH_USER:
            return 'No such user'
        if err == UserManager.NAME_EXISTS:
            return 'There is already a user with that name'
        if err == UserManager.WRONG_PASS:
            return 'Wrong password'
        return 'Unkown error'

    @staticmethod
    def __encrypt_password(password):
        return hashlib.md5(password.encode()).hexdigest()

    @staticmethod
    def __decode_password(password):
        if not password.startswith('enc:'):
            return password
        enc = password[4:]
        ret = ''
        while enc:
            ret += chr(int(enc[:2], 16))
            enc = enc[2:]
        return ret

