def _hash_password(password, salt):
    return hashlib.md5(password.encode()).hexdigest()


def _generate_salt():
    return os.urandom(16).hex()


def _verify_password(hashed, clear):
    salt = hashed[:32]
    to_compare = _hash_password(clear, salt)
    return hashed == to_compare


class UserDatabaseMethods:
    @style.queue
    def check_auth(self, user, password):
        query = (
            "SELECT id, name, password, role, permission, template, email "
            "FROM users WHERE name=?"
        )
        self.c.execute(query, (user,))
        r = self.c.fetchone()
        if not r:
            return {}

        stored_password = r[2]
        if not _verify_password(stored_password, password):
            return {}

        return {
            "id": r[0],
            "name": r[1],
            "role": r[3],
            "permission": r[4],
            "template": r[5],
            "email": r[6],
        }

    @style.queue
    def add_user(self, user, password, role=0, perms=0, reset=False):
        salt_pw = _hash_password(password, _generate_salt())

        select_query = "SELECT name FROM users WHERE name=?"
        self.c.execute(select_query, (user,))
        if self.c.fetchone() is not None:
            if reset:
                update_query = (
                    "UPDATE users SET password=?, role=?, permission=? WHERE name=?"
                )
                self.c.execute(update_query, (salt_pw, role, perms, user))
                return True
            return False

        insert_query = (
            "INSERT INTO users (name, password, role, permission) "
            "VALUES (?, ?, ?, ?)"
        )
        self.c.execute(insert_query, (user, salt_pw, role, perms))
        return True

    @style.queue
    def change_password(self, user, old_password, new_password):
        select_query = "SELECT id, name, password FROM users WHERE name=?"
        self.c.execute(select_query, (user,))
        r = self.c.fetchone()
        if not r:
            return False

        stored_password = r[2]
        if not _verify_password(stored_password, old_password):
            return False

        newpw = _hash_password(new_password, _generate_salt())

        update_query = "UPDATE users SET password=? WHERE name=?"
        self.c.execute(update_query, (newpw, user))
        return True

    @style.async_
    def set_permission(self, user, perms):
        query = "UPDATE users SET permission=? WHERE name=?"
        self.c.execute(query, (perms, user))

    @style.async_
    def set_role(self, user, role):
