    @classmethod
    def fromdict(cls, d):
        allowed = (
            'name', 'email', 'passwordhash', 'phone', 'last_active', 'birthdate',
            'bio', 'gender', 'org_id', 'is_poc'
        )
        df = {k: v for k, v in d.items() if k in allowed}
        return cls(**df)

    def asdict(self):
        result = {}
        for key in self.__mapper__.c.keys():
            value = getattr(self, key)
            if isinstance(value, date):
                result[key] = str(value)
            else:
                result[key] = value
        return result

